		"zcnhrmecn_ta01/view/Master.view.xml": "<mvc:View controllerName=\"zcnhrmecn_ta01.controller.Master\" xmlns:mvc=\"sap.ui.core.mvc\" xmlns:core=\"sap.ui.core\" xmlns=\"sap.m\"\r\n\txmlns:semantic=\"sap.m.semantic\">\r\n\t<semantic:MasterPage id=\"page\" title=\"{masterView>/title}\" navButtonPress=\"onNavHome\" showNavButton=\"true\">\r\n\t\t<semantic:subHeader>\r\n\t\t\t<Bar id=\"headerBar\">\r\n\t\t\t\t<contentMiddle>\r\n\t\t\t\t\t<SearchField id=\"searchField\" showRefreshButton=\"{= !${device>/support/touch} }\" tooltip=\"{i18n>masterSearchTooltip}\" width=\"100%\"\r\n\t\t\t\t\t\tsearch=\"onSearch\"></SearchField>\r\n\t\t\t\t</contentMiddle>\r\n\t\t\t</Bar>\r\n\t\t</semantic:subHeader>\r\n\t\t<semantic:content>\r\n\t\t\t<PullToRefresh id=\"pullToRefresh\" visible=\"{device>/support/touch}\" refresh=\"onRefresh\"/>\r\n\t\t\t<!-- For client side filtering add this to the items attribute:  parameters: {operationMode: 'Client'}}\" -->\r\n\t\t\t<List id=\"List\" updateFinished=\"onUpdateFinished\" noDataText=\"{i18n>NoRecord}\" growing=\"true\" growingScrollToLoad=\"false\"\r\n\t\t\t\tgrowingThreshold=\"25\" selectionChange=\"onNavApprove\" mode=\"{= ${device>/system/phone} ? 'None' : 'SingleSelectMaster'}\">\r\n\t\t\t\t<ObjectListItem id=\"ObjectListItem\" title=\"{parts :['Nachn','Vorna','Rufnm'], formatter:'._formatName'}\"\r\n\t\t\t\t\ttype=\"{= ${device>/system/phone} ? 'Active' : 'Inactive'}\" press=\"onNavApprove\" number=\"{Stdaz}\" numberUnit=\"{i18n>Hours}\">\r\n\t\t\t\t\t<firstStatus>\r\n\t\t\t\t\t\t<ObjectStatus text=\"{StatsDes}\" state=\"{parts :['Stats'], formatter:'._formatText'}\"/>\r\n\t\t\t\t\t</firstStatus>\r\n\t\t\t\t\t<attributes>\r\n\t\t\t\t\t\t<ObjectAttribute text=\"{Zlvde}\"/>\r\n\t\t\t\t\t\t<ObjectAttribute\r\n\t\t\t\t\t\t\ttext=\"{path: 'Begda', type: 'sap.ui.model.type.Date', formatOptions: { pattern : 'yyyy.MM.dd' }} - {path: 'Endda', type: 'sap.ui.model.type.Date', formatOptions: { pattern : 'yyyy.MM.dd' }}\"/>\r\n\t\t\t\t\t\t<ObjectAttribute\r\n\t\t\t\t\t\t\ttext=\"{path: 'Beguz', type: 'sap.ui.model.odata.type.Time', formatOptions: { pattern : 'HH:mm:ss' }} - {path: 'Enduz', type: 'sap.ui.model.odata.type.Time', formatOptions: { pattern : 'HH:mm:ss' }}\"/>\r\n\t\t\t\t\t</attributes>\r\n\t\t\t\t</ObjectListItem>\r\n\t\t\t</List>\r\n\t\t</semantic:content>\r\n\t</semantic:MasterPage>\r\n</mvc:View>",
		"zcnhrmecn_ta01/view/Login.fragment.xml": "<core:FragmentDefinition xmlns=\"sap.m\" xmlns:l=\"sap.ui.layout\" xmlns:f=\"sap.ui.layout.form\" xmlns:core=\"sap.ui.core\">\r\n\t<Dialog title=\"{i18n>DialogTitle}\" id=\"Msgdialog\">\r\n\t\t<Panel width=\"auto\" class=\"sapUiTinyMargin\">\r\n\t\t\t<HBox justifyContent=\"Center\" width=\"100%\">\r\n\t\t\t\t<Image src=\"{imageModel>/path}/images/checkphone.png\"/>\r\n\t\t\t</HBox>\r\n\t\t\t<l:VerticalLayout class=\"sapUiContentPadding\" width=\"100%\">\r\n\t\t\t\t<l:content>\r\n\t\t\t\t\t<VBox>\r\n\t\t\t\t\t\t<Input id=\"InputPhone\" width=\"88%\" type=\"Tel\" maxLength=\"11\" placeholder=\"{i18n>InputPhone}\" valueState=\"{masterView>/valueState}\"\r\n\t\t\t\t\t\t\tclass=\"sapUiSmallMarginBegin\"/>\r\n\t\t\t\t\t\t<Label id=\"labelPhone\" text=\"\" class=\"sapUiSmallMarginBegin color\"/>\r\n\t\t\t\t\t</VBox>\r\n\t\t\t\t\t<HBox >\r\n\t\t\t\t\t\t<Input id=\"InputVid\" width=\"80%\" type=\"Tel\" maxLength=\"4\" placeholder=\"{i18n>InputValidate}\" class=\"sapUiSmallMarginBegin\"\r\n\t\t\t\t\t\t\tvalueState=\"{masterView>/valueState1}\"/>\r\n\t\t\t\t\t\t<Button text=\"{masterView>/validatecode}\" id=\"Sendcode\" press=\"onCreateCode\" enabled=\"{masterView>/buttonenabled}\"\r\n\t\t\t\t\t\t\tbusy=\"{masterView>/busyCode}\" class=\"radius\"/>\r\n\t\t\t\t\t</HBox>\r\n\t\t\t\t\t<Label id=\"labelMsg\" text=\"\" class=\"sapUiSmallMarginBegin color\"/>\r\n\t\t\t\t</l:content>\r\n\t\t\t</l:VerticalLayout>\r\n\t\t</Panel>\r\n\t\t<beginButton>\r\n\t\t\t<Button type=\"Accept\" text=\"{i18n>Enter}\" press=\"onValidate\" enabled=\"{masterView>/labelenabled}\"></Button>\r\n\t\t</beginButton>\r\n\t\t<endButton>\r\n\t\t\t<Button text=\"{i18n>Cancel}\" press=\"onNavHome\"></Button>\r\n\t\t</endButton>\r\n\t</Dialog>\r\n</core:FragmentDefinition>",
